"""Oracle for `whisper_create_sinusoids` — generated by `pipeline/build_oracle.py`.

Reference comes from `pipeline/models.py::whisper_create_sinusoids` (numpy version).
Test passes the kernel's logical inputs and compares against the numpy reference.
"""

import numpy as np
import torch
import torch.testing

_EXTRA_ARGS = ()            # compile-time constants for the np reference

# Make the numpy reference importable without the JAX dep — we import lazily.
def _ref(*args):
    import sys, pathlib
    pipe = pathlib.Path(__file__).resolve().parents[1] / "pipeline"
    if str(pipe) not in sys.path:
        sys.path.insert(0, str(pipe))
    import models as _m
    return _m.get('whisper_create_sinusoids').np_reference(*args, *_EXTRA_ARGS)


_INPUT_SPECS = [((1024,), 'float32'), ((256,), 'float32')]          # [(shape, dtype_str), ...] — main bench size
_BENCH_CASES = [{'label': 'rep1', 'shapes': [[1024], [256]]}, {'label': 'rep2', 'shapes': [[1024], [256]]}, {'label': 'rep3', 'shapes': [[1024], [256]]}]          # list of {label, shapes:[..]} dicts
_RTOL = 0.001
_ATOL = 0.001


def _make_inputs(shapes, seed=42):
    rng = np.random.default_rng(seed)
    out = []
    for spec, shape in zip(_INPUT_SPECS, shapes):
        dtype = np.dtype(spec[1])
        if np.issubdtype(dtype, np.floating):
            arr = rng.standard_normal(shape).astype(dtype)
        else:
            arr = rng.integers(0, 16, size=shape).astype(dtype)
        out.append(torch.tensor(arr))
    return out


def run_test(wrapper):
    # Tiny shape sweep that mirrors the bench cases (we just use the medium one
    # to keep test wall-clock manageable). The kernel was specialized to the
    # main bench shape, so we only test that shape.
    shapes = _BENCH_CASES[len(_BENCH_CASES) // 2]["shapes"]
    inputs = _make_inputs(shapes)
    result = wrapper(*inputs)
    ref = torch.as_tensor(_ref(*[t.numpy() for t in inputs]))
    torch.testing.assert_close(result.float(), ref.float(), rtol=_RTOL, atol=_ATOL)
    print("Test passed")


def bench(wrapper):
    shapes = _BENCH_CASES[len(_BENCH_CASES) // 2]["shapes"]
    inputs = _make_inputs(shapes)
    wrapper(*inputs)
    print("Bench setup passed")


def bench3(wrapper, idx):
    cases = _BENCH_CASES
    if idx >= len(cases):
        raise IndexError(f"bench3 idx={idx} but only {len(cases)} cases")
    shapes = cases[idx]["shapes"]
    inputs = _make_inputs(shapes)
    wrapper(*inputs)
    print("Bench setup passed")
